"""Turn the buyer guide into a useful, private first-call companion."""
import shutil


def add(out, origin, pages):
    why='''<section class="wrap why-local" aria-labelledby="why-local-title"><div class="why-local-intro"><div class="eyebrow">WHY CHOOSE A WAZOOZIE CONNECTION?</div><h2 id="why-local-title">Good reputations deserve<br><em>a bigger stage.</em></h2><p>Small businesses. Skilled people. Local affiliates with a name to stand behind. Wazoozie helps you get past the pitch and start a better conversation.</p></div><div class="why-local-grid"><article><span>01 / KNOW THE NAME</span><h3>Meet a business.<br>Skip the mystery.</h3><p>See the named business or professional before deciding who to contact. Your next step stays your choice.</p><a href="/local-help/">Explore the local shortlist →</a></article><article><span>02 / READ THE CONTEXT</span><h3>A recommendation<br>with a reason.</h3><p>Read the listing’s evidence and relationship disclosures. New owner-recommended profiles link public sources and explain what has not been independently checked.</p><a href="/our-standards/">See how listings work →</a></article><article><span>03 / TALK TO THE PEOPLE</span><h3>Less runaround.<br>A clearer first call.</h3><p>Use the direct contact details, bring your questions and agree on scope and pricing with the business doing the work.</p><a href="/before-you-say-yes/">Take the better questions →</a></article></div></section>'''
    home=out/'index.html';s=home.read_text();marker='<section class="concierge-home wrap grand-finder"';assert marker in s
    home.write_text(s.replace(marker,why+marker,1))
    decoder='''<section id="offer-decoder" class="offer-decoder" aria-labelledby="offer-decoder-title"><div class="decoder-intro"><div class="eyebrow">FINE PRINT THEATER · THE OPENING ACT</div><h2 id="offer-decoder-title">A $49 visit.<br><em>And then what?</em></h2><p class="decoder-lede">Great price. Now ask the great question: <strong>“What will I owe if I don’t approve any repairs?”</strong></p><figure class="decoder-character"><img src="/assets/clay-fine-print-pitchman.webp" alt="Fictional clay-style sales character with a $49 tune-up ticket and a jumble of add-on slips" width="1200" height="800" loading="lazy" decoding="async"><figcaption>Our fictional fine-print fellow. A little satire, a useful question.</figcaption></figure><p>A small headline price can be a perfectly good offer. What matters is the complete visit: what’s included, what’s extra and what needs your approval.</p><div class="decoder-three"><article><span>01</span><h3>The arrival.</h3><p>Is that the dispatch fee, the whole visit, or a promotion with conditions?</p></article><article><span>02</span><h3>The answer.</h3><p>Is diagnosis included? What checks do you get for that price?</p></article><article><span>03</span><h3>The work.</h3><p>Will you get the findings and a written price before deciding on repairs?</p></article></div><details class="decoder-call-script"><summary>Take this 20-second script.</summary><p>“Before I book, what’s the full amount if I decide against repairs? What checks are included? Are there separate fees or conditions? Please get my approval before doing additional work.”</p><p><a href="/before-you-say-yes/#fine-print-theater">More good questions from Fine Print Theater →</a></p></details></div><div class="decoder-workspace"><div class="decoder-receipt-heading"><span class="eyebrow">THE WHOLE-VISIT CHECK</span><p>The headline is one line.<br><strong>Let’s see the rest.</strong></p></div><form id="offer-form" hidden novalidate><fieldset><legend>What would I owe before repairs?</legend><label for="offer-visit">Advertised visit / dispatch charge ($)</label><input id="offer-visit" name="visit" type="text" inputmode="decimal" maxlength="12" placeholder="Ask the business" autocomplete="off" aria-describedby="offer-amount-help"><label for="offer-diagnostic">Additional diagnosis, only if separate ($)</label><input id="offer-diagnostic" name="diagnostic" type="text" inputmode="decimal" maxlength="12" placeholder="Included? Enter a confirmed 0" autocomplete="off" aria-describedby="offer-amount-help"><label for="offer-extras">Other required charges and taxes ($)</label><input id="offer-extras" name="extras" type="text" inputmode="decimal" maxlength="12" placeholder="Ask about the complete amount" autocomplete="off" aria-describedby="offer-amount-help"><p id="offer-amount-help">Use confirmed amounts for the same visit. Leave unknown charges blank; enter 0 only when there’s no extra charge. Count an included diagnosis once.</p></fieldset><div class="decoder-actions"><button class="btn primary" type="submit">Show my visit total →</button><button class="btn outline" type="reset">Start fresh</button></div><div class="decoder-examples"><span>JUST TRYING IT? TWO FICTIONAL EXAMPLES:</span><button class="decoder-example" id="offer-included-example" type="button">$49, with diagnosis included</button><button class="decoder-example" id="offer-example" type="button">$49 + a separate $150 diagnosis</button></div><div id="offer-receipt" class="offer-receipt" hidden><span id="offer-receipt-label"></span><strong id="offer-total"></strong><span>Before repairs · based on the amounts above</span></div><p id="offer-result" role="status" aria-live="polite">The full visit price starts with three clear answers.</p><details id="offer-notes-panel" hidden><summary>Your first-call notes · review or copy</summary><label for="offer-notes">Review your notes</label><textarea id="offer-notes" rows="8" readonly placeholder="Your result and questions will appear here."></textarea><button class="btn outline" id="offer-copy" type="button" disabled>Copy my call notes</button><p id="offer-copy-status" role="status" aria-live="polite"></p></details><small>This tool adds your inputs; it doesn’t verify offers or estimate repairs. Entries stay in this page and aren’t saved or sent.</small></form><noscript><p>Ask for the visit charge, any separate diagnosis and other required fees or taxes. Add the confirmed amounts. If a charge is unknown, ask before booking.</p></noscript></div></section>'''
    for path in ('pricing-guide','before-you-say-yes'):
        target=out/path/'index.html';s=target.read_text()
        marker='<section id="method"' if path=='pricing-guide' else '<nav class="buying-jumps"'
        assert marker in s;s=s.replace(marker,decoder+marker,1)
        s=s.replace('</body>','<script type="module" src="/assets/offer-decoder.js"></script></body>')
        if path=='pricing-guide':s=s.replace('aria-label="Price guide sections">','aria-label="Price guide sections"><a href="#offer-decoder">Decode a service-call offer</a>',1)
        target.write_text(s)
    for path in (out/'index.html',out/'pricing-guide/index.html',out/'before-you-say-yes/index.html'):
        path.write_text(path.read_text().replace('</head>','<link rel="stylesheet" href="/assets/buyer-edge.css"></head>',1))
    for asset in ('buyer-edge.css','offer-decoder.js'):
        shutil.copy(out.parent/'assets'/asset,out/'assets'/asset)
